    return heading('S1 / DISCLOSURE RULES','披露规范工作台','需要披露什么、为何适用、原始要求在哪里。',b('发布清单版本','publishChecklist',{},'btn-primary',ro()||g.checklist.status==='published')+share())+'<div class="between mb"><div class="chips"><span class="badge">'+h(g.project.market)+'</span><span class="badge">'+h(g.project.framework)+'</span>'+badge(g.checklist.status)+'<span class="mono">清单 v'+g.checklist.version+'</span></div><div class="actions">'+ai('生成检查项','draft','check',[id],'newCheck')+ai('拆分','draft','check',scope,'split')+ai('合并','merge','check',scope,'merge')+ai('改写','rewrite','check',scope)+'</div></div>'+U.searchbar('搜索检查项、主题或披露要求…')+section('披露检查清单','<div class="table-scroll"><table class="data-table"><thead><tr><th aria-label="选择"></th><th>检查项 / 披露类型</th><th>覆盖状态</th><th>主条款 / 指引</th><th>已映射文件 / 事实 / 要点</th><th>版本 / 审核</th></tr></thead><tbody>'+rows+'</tbody></table></div>')+'<div class="two-column mt">'+section('监管原文与关联说明',preview,b('展开原文','openFile',{type:'check',id},'btn-small'))+section('执行要求与适用逻辑','<h3>'+h(c.title)+'</h3><p>'+h(c.summary)+'</p><p class="small">'+h(c.applicability)+'</p><div class="chips">'+c.evidenceTypes.map(t=>'<span class="badge">'+h(t)+'</span>').join('')+'</div><div class="hr"></div><div class="meta">最后审核：'+h(c.reviewedBy||'待审核')+'</div><div class="actions mt">'+link('mapping','check',id,'查看证据与覆盖详情 →')+b('查看清单 Diff','diff',{type:'check',id},'btn-small')+'</div>')+'</div>';
