    const controls='<div class="actions">'+ai('总结文件','extract','file',[file.id],'summarize')+ai('比较版本','compare','file',g.files.filter(f=>f.family===file.family&&f.type===file.type).map(f=>f.id),'compareFiles')+ai('提取事实','extract','file',[file.id],'extractFacts')+ai('建议映射','map','file',[file.id])+'</div>';
