    return heading('S2–S3 / INTAKE & TRACEABILITY','收资文件工作台','从文件内容出发，追查它支持的披露要求与事实版本。',b(icon('upload')+'导入虚构样例','importFile',{},'btn-primary',ro())+share())+U.searchbar('搜索文件名、路径或证据…')+(!rows.some(f=>f.id===file.id)?notice('定位文件被共享筛选隐藏，当前详情保留。'+b('清除条件','clearFilters',{},'btn-small')):'')+'<div class="triple file-workspace">'+section('收资文件',navigation)+'<div class="stack"><div class="between"><div class="inline">'+U.fileType(file)+'<div><h2 class="break">'+h(file.name)+'</h2><span class="meta">'+h(file.date+' · '+file.size)+'</span></div></div></div>'+controls+(file.status==='error'?notice('扫描表格无法可靠识别。失败原件保留，清晰副本需作为新收资文件进入。'+b('导入清晰演示副本','importFile',{template:'FILE-SCAN'},'btn-small',ro()),'danger'):file.status==='registered'?notice('文件已登记，等待模拟解析。'+b('解析文件','parseFile',{id:file.id},'btn-small',ro()),'info'):'')+section('文件内容与定位',U.documentPreview(file,loc),b('展开证据','evidence',{file:file.id,locator:loc?.id},'btn-small'))+'<div class="actions">'+b('选择片段并创建映射','createFileMapping',{id:file.id},'btn-primary',ro()||['error','registered'].includes(file.status))+b('归入 Family','assignFamily',{id:file.id},'',ro()||['error','registered'].includes(file.status))+(file.family?link('sources','family',file.family,'审核权威来源 →'):'')+'</div>'+section('关联披露检查项',targets)+'</div><aside class="evidence-pane stack">'+section('文件身份与版本',info,b('上一版 Diff','diff',{type:'file',id:file.id},'btn-small'))+section('事实版本',facts.map(f=>'<div class="mb">'+link('facts','fact',f.id,h(f.title+' · '+f.displayValue+' '+f.unit),{},'small')+'<div class="mt">'+badge(f.status)+'</div></div>').join('')||empty('尚未形成事实候选','提取结果先进入事实审核。'))+'</aside></div><details class="narrow-file-info mt"><summary>文件身份、路径及解析详情</summary>'+info+'</details>';
