  U.handlers.createFileMapping=p=>{const g=E.state(), locs=g.locators.filter(l=>l.fileId===p.id), facts=g.facts.filter(f=>E.effective(g,f)&&f.locatorIds.some(id=>locs.some(l=>l.id===id)));U.ask('选择片段与披露要求',field('check','目标检查项',selectInput('check',g.checks.map(c=>[c.id,c.title]),g.checks[0].id))+field('locator','原始位置',selectInput('locator',locs.length?locs.map(l=>[l.id,l.position]):[['','尚无可审核定位；先提取事实']],locs[0]?.id))+notice('下一步核对关联事实和覆盖理由。未形成有效事实时，不得直接标为已覆盖。','info'),'继续确认映射',v=>{U.closeDialog();U.handlers.editMapping({id:v.check,factIds:facts.filter(f=>f.locatorIds.includes(v.locator)).map(f=>f.id)});return false;});};
